 function reload(){if(player.ammo<24&&player.reserve>0){let n=Math.min(24-player.ammo,player.reserve);player.ammo+=n;player.reserve-=n;document.getElementById('ammo').textContent=player.ammo;toast(`RELOADED · ${player.ammo} / ${player.reserve}`)}}function placeBarricade(){if(selected!==1)return;if(+hotItems[1][2]<=0){toast('NO BARRICADES LEFT');return}let x=Math.floor(player.x+Math.cos(player.a)*1.6),y=Math.floor(player.y+Math.sin(player.a)*1.6);if(cell(x,y)==='.'&&!solid(x,y)){map[y]=map[y].slice(0,x)+'6'+map[y].slice(x+1);hotItems[1][2]=String(+hotItems[1][2]-1);barricades++;renderHotbar();document.getElementById('objDetail').textContent=`Place 3 barricades · ${Math.min(barricades,3)} / 3`;document.getElementById('objProgress').style.width=`${Math.min(barricades/3*100,100)}%`;if(barricades>=3){document.getElementById('objective').textContent='PERIMETER SECURED';toast('OBJECTIVE COMPLETE · +250 XP')}else toast('BARRICADE DEPLOYED')}else toast('NO ROOM TO BUILD')}
