 function render(){let now=performance.now(),dt=Math.min((now-last)/1000,.05);last=now;time+=dt;frame++;if(active&&!paused&&!inventory)update(dt);draw(dt);requestAnimationFrame(render)}
 function update(dt){let f=0,s=0;if(keys.w||keys.arrowup)f++;if(keys.s||keys.arrowdown)f--;if(keys.d) s++;if(keys.a)s--;let run=keys.shift&&player.stamina>2, crouch=keys.control;let speed=run?3.4:crouch?1.05:2.05;if(run&&f){player.stamina=Math.max(0,player.stamina-dt*18)}else player.stamina=Math.min(100,player.stamina+dt*9);let l=Math.hypot(f,s)||1,dx=(Math.cos(player.a)*f-Math.sin(player.a)*s)/l*speed*dt,dy=(Math.sin(player.a)*f+Math.cos(player.a)*s)/l*speed*dt;if(!solid(player.x+dx+.19*Math.sign(dx),player.y))player.x+=dx;if(!solid(player.x,player.y+dy+.19*Math.sign(dy)))player.y+=dy;player.speed=Math.hypot(dx,dy)/dt;walk+=player.speed*dt*4;document.getElementById('staminaNum').textContent=Math.round(player.stamina);document.getElementById('staminaBar').style.width=player.stamina+'%';if(frame%240===0){let e=enemies.find(x=>x.alive);if(e&&Math.random()<.45){player.health=Math.max(1,player.health-4);document.getElementById('healthNum').textContent=player.health;document.getElementById('healthBar').style.width=player.health+'%';damageFlash=.45;toast('HOSTILE FIRE · VITALS -4')}}if(frame%480===0){let min=Math.floor(time/60)+18;document.getElementById('clock').textContent=`${String((18+Math.floor(min/60))%24).padStart(2,'0')}:${String(min%60).padStart(2,'0')}`}}
 function draw(dt){let w=W,h=H,horizon=h*.49+Math.sin(walk)*Math.min(player.speed*.8,4),fov=1.03+(keys.shift?.13:0),cols=Math.min(Math.ceil(w/2),600),step=w/cols,depth=new Float32Array(cols);let sky=ctx.createLinearGradient(0,0,0,horizon);sky.addColorStop(0,'#1c2929');sky.addColorStop(.52,'#50605b');sky.addColorStop(1,'#c09168');ctx.fillStyle=sky;ctx.fillRect(0,0,w,horizon+2);ctx.fillStyle='#bd8962';ctx.globalAlpha=.16;ctx.beginPath();ctx.ellipse(w*.5,horizon-20,w*.5,42,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;

